const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

(async () => {
  const htmlPath = path.resolve('output/coding-ai-leaderboard.html');
  const outPath = path.resolve('output/final_poster.png');
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 1080, height: 1350, deviceScaleFactor: 2 });
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0' });
  await page.waitForTimeout(250);
  const poster = await page.$('#posterRoot');
  await poster.screenshot({ path: outPath });
  await browser.close();
  const stats = fs.statSync(outPath);
  console.log('wrote', outPath, 'bytes', stats.size);
})();
